import{_ as i,y as n,a as o,o as t,a6 as a,c as d,w as s,I as h,D as l,a7 as u}from"./chunks/framework.CJDy2q7X.js";const E=JSON.parse('{"title":"Returns / RMA (Admin)","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/admin/returns-rma.md","filePath":"api/workflows/admin/returns-rma.md","lastUpdated":1787725411000}'),p={name:"api/workflows/admin/returns-rma.md"};function c(m,e,f,g,k,q){const r=n("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a('<h1 id="returns-rma-admin" tabindex="-1">Returns / RMA (Admin) <a class="header-anchor" href="#returns-rma-admin" aria-label="Permalink to &quot;Returns / RMA (Admin)&quot;">​</a></h1><p>Process the return requests customers raise on the storefront: review the queue, move a request through its status chain, exchange messages with the customer, and reopen a closed request. This is the back-office half of the storefront <a href="/api/workflows/shop/returns-rma.html">Returns / RMA</a> flow.</p><p>Every call below links to its <strong>REST</strong> endpoint page for concreteness. The sequence is transport-agnostic — the same flow works over GraphQL with the equivalent query or mutation, and each REST page cross-links to its GraphQL twin. Pick whichever transport your client uses; only the request shape changes, never the order of steps.</p><h2 id="agent-ask-inputs" tabindex="-1">Agent-ask inputs <a class="header-anchor" href="#agent-ask-inputs" aria-label="Permalink to &quot;Agent-ask inputs&quot;">​</a></h2><ul><li><strong>Integration token</strong> — ask the user; send as <code>Authorization: Bearer &lt;id&gt;|&lt;token&gt;</code>. Reads need the RMA-requests permission; creating a return needs its create permission. A missing permission returns 403.</li><li><strong>Server URL</strong> — ask the user for their Bagisto server&#39;s base URL (e.g. <code>https://store.example.com</code>) and prefix every endpoint path with it. Never assume localhost or a demo domain.</li></ul><h2 id="two-separate-surfaces" tabindex="-1">Two separate surfaces <a class="header-anchor" href="#two-separate-surfaces" aria-label="Permalink to &quot;Two separate surfaces&quot;">​</a></h2><p>The menu splits into the <strong>queue</strong> — the requests themselves, under Sales — and the <strong>reference data</strong> that governs it, under Settings. Both live under the same <code>/api/admin/rma/</code> path prefix even though the admin panel shows them in different menus, which is the first thing that trips people up.</p><table tabindex="0"><thead><tr><th>Surface</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>Requests</td><td><code>/api/admin/rma/requests</code></td><td>The queue: list, view, create, status changes, reopen</td></tr><tr><td>Messages</td><td><code>/api/admin/rma/messages</code></td><td>The conversation attached to a request</td></tr><tr><td>Reasons</td><td><code>/api/admin/rma/reasons</code></td><td>Why a customer may return — offered on the storefront form</td></tr><tr><td>Statuses</td><td><code>/api/admin/rma/statuses</code></td><td>The status vocabulary a request moves through</td></tr><tr><td>Rules</td><td><code>/api/admin/rma/rules</code></td><td>Eligibility: the return window and what qualifies</td></tr><tr><td>Custom fields</td><td><code>/api/admin/rma/custom-fields</code></td><td>Extra fields captured on the request form</td></tr></tbody></table><p>Set up the reference data before expecting the storefront form to work — a store with no active reason gives the customer nothing to pick.</p><h2 id="the-queue-flow" tabindex="-1">The queue flow <a class="header-anchor" href="#the-queue-flow" aria-label="Permalink to &quot;The queue flow&quot;">​</a></h2>',10)),(t(),d(u,null,{default:s(()=>[l(r,{id:"mermaid-119",class:"mermaid",graph:"flowchart%20TD%0A%20%20list%5BGET%20rma%2Frequests%3Cbr%2F%3Ethe%20queue%5D%20--%3E%20detail%5BGET%20rma%2Frequests%2Fid%3Cbr%2F%3Efull%20request%20%2B%20availableStatuses%5D%0A%20%20detail%20--%3E%20decide%7BAction%3F%7D%0A%20%20decide%20--%20move%20it%20on%20--%3E%20status%5BPOST%20id%2Fupdate-status%3Cbr%2F%3Epick%20from%20availableStatuses%5D%0A%20%20decide%20--%20ask%20the%20customer%20--%3E%20msg%5BPOST%20rma%2Fmessages%5D%0A%20%20decide%20--%20closed%20too%20early%20--%3E%20reopen%5BPOST%20id%2Freopen%3Cbr%2F%3Eonly%20when%20canReopen%5D%0A%20%20msg%20--%3E%20detail%0A%20%20status%20--%3E%20detail%0A"})]),fallback:s(()=>e[0]||(e[0]=[h(" Loading... ",-1)])),_:1})),e[2]||(e[2]=a(`<table tabindex="0"><thead><tr><th>#</th><th>Step</th><th>Call</th></tr></thead><tbody><tr><td>1</td><td>List the queue</td><td><a href="/api/rest-api/admin/sales/returns/list-returns.html">List Returns</a></td></tr><tr><td>2</td><td>Open one request</td><td><a href="/api/rest-api/admin/sales/returns/get-return.html">Get Return</a></td></tr><tr><td>3</td><td>Move its status</td><td><a href="/api/rest-api/admin/sales/returns/update-status.html">Update Status</a></td></tr><tr><td>4</td><td>Read the conversation</td><td><a href="/api/rest-api/admin/sales/returns/list-return-messages.html">List Return Messages</a></td></tr><tr><td>5</td><td>Reply to the customer</td><td><a href="/api/rest-api/admin/sales/returns/send-return-message.html">Send Return Message</a></td></tr><tr><td>6</td><td>Reopen a closed request</td><td><a href="/api/rest-api/admin/sales/returns/reopen-return.html">Reopen Return</a></td></tr></tbody></table><h2 id="never-hard-code-the-status-list" tabindex="-1">Never hard-code the status list <a class="header-anchor" href="#never-hard-code-the-status-list" aria-label="Permalink to &quot;Never hard-code the status list&quot;">​</a></h2><p>A request carries <code>statusId</code>, <code>statusTitle</code>, and <code>statusColor</code> — but the field that matters when you build a UI is <strong><code>availableStatuses</code></strong> on the detail response. It lists only the transitions legal <em>from where the request currently stands</em>, as <code>{ id, title }</code> pairs:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;availableStatuses&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Approved&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Request Declined&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Render your status dropdown from that array and pass the chosen <code>id</code> to update-status. The full vocabulary from <a href="/api/rest-api/admin/settings/return-statuses/list.html">List Statuses</a> is the <em>catalogue</em>, not the set of legal next moves — a request sitting at &quot;Pending Review&quot; cannot jump straight to &quot;Refunded&quot;, and offering that choice produces a rejected call.</p><p>The nine shipped statuses are Pending Review, Approved, Awaiting Return, Return In Transit, Refunded, Solved, Request Declined, Item Canceled, and Request Canceled. All are editable, so treat titles as data rather than constants.</p><h2 id="reopening" tabindex="-1">Reopening <a class="header-anchor" href="#reopening" aria-label="Permalink to &quot;Reopening&quot;">​</a></h2><p><code>canReopen</code> on the detail response tells you whether the reopen action applies — it is only meaningful once a request has reached a closed state. Show the button from that boolean rather than inferring it from the status title, which is editable and translatable.</p><h2 id="creating-a-return-as-the-admin" tabindex="-1">Creating a return as the admin <a class="header-anchor" href="#creating-a-return-as-the-admin" aria-label="Permalink to &quot;Creating a return as the admin&quot;">​</a></h2><p>Admins can raise a return on the customer&#39;s behalf, which is how a phone or email request gets into the system. It needs two lookups first:</p><ol><li><a href="/api/rest-api/admin/sales/returns/list-returnable-items.html">Returnable Items</a> — which of the order&#39;s items are still eligible, given the return window from the active rule.</li><li><a href="/api/rest-api/admin/sales/returns/list-return-reasons.html">Return Reasons</a> — filtered by <code>resolutionType</code>, because a reason may permit a return, a cancellation, or both.</li></ol><p>Then <a href="/api/rest-api/admin/sales/returns/create-return.html">Create Return</a> with the order, the items, and the chosen reason.</p><p>A reason carries an <code>isAdmin</code> flag. Reasons flagged admin-only never appear on the storefront form and exist for exactly this path — so the list an admin sees can legitimately be longer than the customer&#39;s.</p><h2 id="reference-data-and-why-the-order-matters" tabindex="-1">Reference data, and why the order matters <a class="header-anchor" href="#reference-data-and-why-the-order-matters" aria-label="Permalink to &quot;Reference data, and why the order matters&quot;">​</a></h2><p>Rules decide <strong>eligibility</strong>, so they gate everything else. A rule defines the return period in days plus what it applies to; the returnable-items lookup is computed against it, and an order outside the window returns nothing eligible no matter how the request is filed. Configure a rule before testing the flow end to end, or the storefront form will look broken when it is behaving correctly.</p><p>Reasons, statuses, and custom fields are ordinary CRUD with mass-delete and mass-update-status, documented under Settings:</p><ul><li><a href="/api/rest-api/admin/settings/return-reasons/list.html">Return Reasons</a></li><li><a href="/api/rest-api/admin/settings/return-statuses/list.html">Return Statuses</a></li><li><a href="/api/rest-api/admin/settings/return-rules/list.html">Return Rules</a></li><li><a href="/api/rest-api/admin/settings/return-custom-fields/list.html">Return Custom Fields</a></li></ul><h2 id="where-this-meets-the-storefront" tabindex="-1">Where this meets the storefront <a class="header-anchor" href="#where-this-meets-the-storefront" aria-label="Permalink to &quot;Where this meets the storefront&quot;">​</a></h2><p>The customer raises and tracks the request through the <a href="/api/workflows/shop/returns-rma.html">storefront RMA flow</a>; the admin sees the same record here. Messages are shared — a reply sent from either side appears in the other&#39;s conversation — so the two flows are one thread, not two.</p>`,19))])}const b=i(p,[["render",c]]);export{E as __pageData,b as default};
